def test_latest_confirmed_period_picks_most_recent_confirmed(session, repo):
    from datetime import datetime, timedelta, timezone

    older = make_confirmed_period(
        session, label="P-OLD", confirmed_at=datetime.now(timezone.utc) - timedelta(days=5)
    )
    newer = make_confirmed_period(session, label="P-NEW")

    result = repo.latest_confirmed_period()
    assert result.id == newer.id
    assert result.id != older.id


