# --- upsert_portfolio_deltas ---------------------------------------------------
# Unit 13: get_or_create_portfolio and every ClientPortfolio mutation inside
# upsert_portfolio_deltas are gone -- client_portfolios is frozen-but-readable.
# Only the DailyClientPortfolio-writing coverage below survives.


def test_upsert_portfolio_deltas_writes_a_balance_row_for_the_run(session, repo):
    user = make_user(session)
    run_id = uuid.uuid4()

    repo.upsert_portfolio_deltas({user.id: Decimal("60")}, run_id, "20260603")

    row = session.get(DailyClientPortfolio, {"run_id": run_id, "user_id": user.id})
    assert row is not None
    assert row.portfolio_amount == Decimal("60")
    assert row.trade_date == "20260603"


def test_upsert_portfolio_deltas_keeps_a_distinct_balance_row_per_run(session, repo):
    """Regression: two calls for the same user with DIFFERENT run_ids must
    each leave their OWN row behind in daily_client_portfolios -- not
    just the latest one."""
    user = make_user(session)
    run_a = uuid.uuid4()
    run_b = uuid.uuid4()

    repo.upsert_portfolio_deltas({user.id: Decimal("-51.55")}, run_a, "20260603")
    repo.upsert_portfolio_deltas({user.id: Decimal("161")}, run_b, "20260604")

    rows = session.query(DailyClientPortfolio).filter_by(user_id=user.id).all()
    by_run = {r.run_id: r.portfolio_amount for r in rows}
    # balances chain: run_b's amount is run_a's amount plus its own delta,
    # not just its own delta in isolation.
    assert by_run == {run_a: Decimal("-51.55"), run_b: Decimal("109.45")}


def test_upsert_portfolio_deltas_chains_balance_across_same_day_model_groups(session, repo):
    """Trap: service.run() calls this once per (trade_date, model) group, so
    a client in two models on the same day gets two rows on the same
    trade_date, written in the same flush (no commit in between -- created_at
    server_default never fires). The second row's balance MUST chain off the
    first row's, not recompute from scratch."""
    user = make_user(session)
    run_a = uuid.uuid4()
    run_b = uuid.uuid4()

    repo.upsert_portfolio_deltas({user.id: Decimal("100")}, run_a, "20260603")
    repo.upsert_portfolio_deltas({user.id: Decimal("-40")}, run_b, "20260603")

    first = session.get(DailyClientPortfolio, {"run_id": run_a, "user_id": user.id})
    second = session.get(DailyClientPortfolio, {"run_id": run_b, "user_id": user.id})
    assert first.portfolio_amount == Decimal("100")
    assert second.portfolio_amount == first.portfolio_amount + Decimal("-40")
    assert second.portfolio_amount == Decimal("60")


def test_upsert_portfolio_deltas_never_commits(session, repo):
    user = make_user(session)
    session.commit = MagicMock(side_effect=AssertionError("repository must not commit"))
    repo.upsert_portfolio_deltas({user.id: Decimal("1")}, uuid.uuid4(), "20260603")


