def test_cells_for_runs_spans_multiple_run_ids(session, repo):
    model = make_model(session)
    user = make_user(session)
    period = make_confirmed_period(session)
    run_a = repo.create_run(
        trade_date="20260603",
        period_id=period.id,
        status=RunStatus.COMPLETED.value,
        trigger=RunTrigger.MANUAL.value,
        grand_total=Decimal("10"),
        run_by=None,
    )
    run_b = repo.create_run(
        # unit A4: trade_date is UNIQUE on post_trade_allocation_runs now, so
        # this second run (to prove cells_for_runs spans run IDS, not dates)
        # must be on a different date.
        trade_date="20260604",
        period_id=period.id,
        status=RunStatus.COMPLETED.value,
        trigger=RunTrigger.SCHEDULED.value,
        grand_total=Decimal("20"),
        run_by=None,
    )
    repo.write_cells(
        [
            {
                "run_id": run_a.id,
                "model_id": model.id,
                "user_id": user.id,
                "model_traded": Decimal("10"),
                "units": Decimal("1"),
                "units_total": Decimal("1"),
                "allocated": Decimal("10"),
                "pct": Decimal("100"),
                "ib_account": "U-1",
                "model_name": model.name,
                "model_acct": "U-1234567",
            },
            {
                "run_id": run_b.id,
                "model_id": model.id,
                "user_id": user.id,
                "model_traded": Decimal("20"),
                "units": Decimal("1"),
                "units_total": Decimal("1"),
                "allocated": Decimal("20"),
                "pct": Decimal("100"),
                "ib_account": "U-1",
                "model_name": model.name,
                "model_acct": "U-1234567",
            },
        ]
    )

    cells = repo.cells_for_runs([run_a.id, run_b.id])
    assert sorted(c.allocated for c in cells) == [Decimal("10"), Decimal("20")]


